-- 0015: long Overview text per part (from the team, 11 Nov). Run after 0014. Safe to re-run.
-- The short description stays under the product title; overview fills the Overview tab.
alter table public.products add column if not exists overview text check (overview is null or char_length(overview) <= 2000);
update public.products set overview = 'The Uprights & Wheel Hub Assembly Kit serves as the critical structural interface between the vehicle’s suspension geometry, braking system, and wheels. Engineered to withstand high cornering loads, braking torque, and dynamic road inputs, this assembly delivers exceptional structural rigidity while minimizing unsprung mass to optimize suspension response and tire contact patch consistency.' where id = 'p-upright-kit';
update public.products set overview = 'The Custom Aerodynamics Package, comprising a multi-element front wing, high-downforce rear wing, and targeted underbody diffuser, is designed using Computational Fluid Dynamics (CFD) to maximize downforce and cornering speeds without introducing excessive aerodynamic drag. It enhances overall vehicle stability during high-speed maneuvering and heavy braking transitions.' where id = 'p-aero-package';
update public.products set overview = 'Integrates the central Vehicle Control Unit (VCU) and Master Battery Management System (BMS) into a single, highly reliable electronic module. Acting as the electronic brain of the EV powertrain, it manages throttle mapping, regenerative braking strategies, real-time telemetry output, and high-voltage safety monitoring (cell voltage, temperature balancing, and fault protection) compliant with strict EV safety regulations.' where id = 'p-vcu-bms';
update public.products set overview = 'The Custom Brake Pedal Box is an ergonomically optimized driver-interface assembly engineered for crisp pedal feel and precise brake bias tuning. Designed specifically for tight cockpit packaging in Formula-style race cars, it features high leverage ratios and dual master cylinders with a balance bar mechanism to allow on-the-fly front-to-rear braking force adjustments.' where id = 'p-pedal-box';
